/// <reference path="../pb_data/types.d.ts" />
function backfillOrigin(app){let p=0;const n=200;while(true){let s;try{s=app.findRecordsByFilter("services","originLocationId = '' || originLocationId = null","+id",n,p*n)}catch(_){return}if(!s||!s.length)break;for(const r of s){const id=r.get("id"),cur=r.get("locationId");let o=null;try{const c=app.findRecordsByFilter("service_events","ServiceId = {:sid} && kind = 'created'","+changedAt",1,0,{sid:id});if(c&&c.length)o=c[0].get("fromLocationId")||c[0].get("toLocationId")||null}catch(_){}if(!o){let has=false;try{const t=app.findRecordsByFilter("service_events","ServiceId = {:sid} && kind = 'location_changed'","id",1,0,{sid:id});has=!!(t&&t.length)}catch(_){}if(!has)o=cur;else{console.log(`[backfill] ambiguous ${id}`);continue}}if(!o)continue;r.set("originLocationId",o);try{app.save(r)}catch(e){console.log(`[backfill] ${id}:${e}`)}}if(s.length<n)break;p++}}onBootstrap((e)=>{e.next();try{backfillOrigin($app)}catch(err){console.log("[backfill] bootstrap",err)}try{cronAdd("backfill-origin","*/5 * * * *",()=>{try{backfillOrigin($app)}catch(err){console.log("[backfill] cron",err)}})}catch(err){console.log("[backfill] cron reg",err)}});
